CREATE TABLE IF NOT EXISTS offices(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,authority TEXT NOT NULL DEFAULT 'Unknown',source_id TEXT REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS appointments(id TEXT PRIMARY KEY,office_id TEXT NOT NULL REFERENCES offices(id),person_id TEXT NOT NULL REFERENCES entities(id),start_date TEXT,end_date TEXT,date_json TEXT NOT NULL,arrangement TEXT NOT NULL DEFAULT 'exclusive',sequence INTEGER,canon TEXT NOT NULL,source_id TEXT REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS chambers(id TEXT PRIMARY KEY,date TEXT NOT NULL,actual_seats INTEGER NOT NULL,occupied_seats INTEGER,legal_min INTEGER,legal_max INTEGER,session_status TEXT NOT NULL,source_id TEXT REFERENCES sources(id),CHECK(occupied_seats<=actual_seats));
CREATE TABLE IF NOT EXISTS party_seats(id TEXT PRIMARY KEY,chamber_id TEXT NOT NULL REFERENCES chambers(id),party TEXT NOT NULL,seats INTEGER NOT NULL CHECK(seats>=0),support TEXT NOT NULL DEFAULT 'Unknown',source_id TEXT REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS bills(id TEXT PRIMARY KEY,identifier TEXT NOT NULL UNIQUE,title TEXT NOT NULL,sponsor TEXT,summary TEXT NOT NULL,introduced_date TEXT,stage TEXT NOT NULL DEFAULT 'draft',effective_date TEXT,source_id TEXT REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS votes(id TEXT PRIMARY KEY,bill_id TEXT NOT NULL REFERENCES bills(id),chamber_id TEXT NOT NULL REFERENCES chambers(id),date TEXT NOT NULL,yes INTEGER NOT NULL,no INTEGER NOT NULL,abstain INTEGER NOT NULL,absent INTEGER NOT NULL,vacancies INTEGER NOT NULL,threshold INTEGER,rule_source TEXT NOT NULL,result TEXT NOT NULL,breakdown TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS units(id TEXT PRIMARY KEY,name TEXT NOT NULL,branch TEXT NOT NULL,unit_type TEXT NOT NULL,formed_date TEXT,disbanded_date TEXT,source_id TEXT REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS unit_states(id TEXT PRIMARY KEY,unit_id TEXT NOT NULL REFERENCES units(id),date TEXT NOT NULL,parent_id TEXT REFERENCES units(id),commander TEXT,garrison TEXT,personnel_low INTEGER,personnel_high INTEGER,authorized INTEGER,readiness TEXT,mission TEXT,supply TEXT,operation TEXT NOT NULL,source_id TEXT REFERENCES sources(id),UNIQUE(unit_id,date));
CREATE TABLE IF NOT EXISTS locations(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,kind TEXT NOT NULL,latitude REAL,longitude REAL,sovereignty TEXT,control TEXT,administration TEXT,source_id TEXT REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS treaties(id TEXT PRIMARY KEY,name TEXT NOT NULL,operation TEXT NOT NULL,date_json TEXT NOT NULL,terms TEXT NOT NULL,signatories TEXT,source_id TEXT REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS restrictions(id TEXT PRIMARY KEY,treaty_id TEXT NOT NULL REFERENCES treaties(id),location_id TEXT NOT NULL REFERENCES locations(id),description TEXT NOT NULL,start_date TEXT,end_date TEXT,scope TEXT NOT NULL DEFAULT 'undated');
CREATE TABLE IF NOT EXISTS movements(id TEXT PRIMARY KEY,unit_id TEXT NOT NULL REFERENCES units(id),location_id TEXT NOT NULL REFERENCES locations(id),date TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN ('planned','ordered','completed','canceled')),mission TEXT NOT NULL,warning TEXT,override_reason TEXT,completed_date TEXT);
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY,name TEXT NOT NULL,type TEXT NOT NULL,operation TEXT NOT NULL,source_id TEXT REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS asset_assignments(id TEXT PRIMARY KEY,asset_id TEXT NOT NULL REFERENCES assets(id),unit_id TEXT NOT NULL REFERENCES units(id),start_date TEXT NOT NULL,end_date TEXT);
CREATE TRIGGER IF NOT EXISTS asset_overlap_insert BEFORE INSERT ON asset_assignments WHEN EXISTS(SELECT 1 FROM asset_assignments a WHERE a.asset_id=NEW.asset_id AND COALESCE(a.end_date,'9999-12-31')>=NEW.start_date AND COALESCE(NEW.end_date,'9999-12-31')>=a.start_date) BEGIN SELECT RAISE(ABORT,'Asset already assigned during interval'); END;
CREATE TABLE IF NOT EXISTS procurement(id TEXT PRIMARY KEY,name TEXT NOT NULL,ordered INTEGER NOT NULL,delivered INTEGER NOT NULL DEFAULT 0,operational INTEGER NOT NULL DEFAULT 0,date TEXT NOT NULL,operation TEXT NOT NULL,source_id TEXT REFERENCES sources(id),CHECK(operational<=delivered AND delivered<=ordered));
CREATE TABLE IF NOT EXISTS battles(id TEXT PRIMARY KEY,name TEXT NOT NULL,date_json TEXT NOT NULL,theater TEXT,outcome TEXT,canon TEXT NOT NULL,source_id TEXT REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS casualties(id TEXT PRIMARY KEY,battle_id TEXT NOT NULL REFERENCES battles(id),unit_id TEXT REFERENCES units(id),report_group TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN ('KIA','WIA','MIA','POW','unspecified')),count INTEGER NOT NULL CHECK(count>=0),canon TEXT NOT NULL,source_id TEXT REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS budgets(id TEXT PRIMARY KEY,name TEXT NOT NULL,fiscal_year INTEGER NOT NULL,currency TEXT NOT NULL,appropriated INTEGER NOT NULL,source_id TEXT REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS ledger(id TEXT PRIMARY KEY,budget_id TEXT NOT NULL REFERENCES budgets(id),date TEXT NOT NULL,stage TEXT NOT NULL CHECK(stage IN ('proposed','authorized','appropriated','committed','disbursed','actual','returned','canceled','transfer')),amount INTEGER NOT NULL CHECK(amount>=0),memo TEXT NOT NULL,override_reason TEXT,source_id TEXT REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,name TEXT NOT NULL,operation TEXT NOT NULL,date_json TEXT NOT NULL,planned INTEGER,approved INTEGER,paid INTEGER,committed INTEGER,currency TEXT,notes TEXT NOT NULL,source_id TEXT REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS event_drafts(id TEXT PRIMARY KEY,title TEXT NOT NULL,date TEXT NOT NULL,actions_json TEXT NOT NULL,operation TEXT NOT NULL DEFAULT 'draft',explanation TEXT,recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
